+namespace sv_530baa3ceff345fb8b21aecdc6f5eb6a.Services;
+
+public class InventoryAlertService
+{
+    private readonly Random _random = new();
+    private int _lastAlertCount;
+
+    public int LastAlertCount => _lastAlertCount;
+
+    /// <summary>
+    /// Fired when polling produces a new alert count. All subscribed
+    /// components re-render, even those that didn't trigger the poll.
+    /// </summary>
+    public event Func<Task>? OnAlertCountChanged;
+
+    /// <summary>
+    /// Simulates a database query that returns the number of items
+    /// below minimum stock levels for the given warehouse.
+    /// </summary>
+    public Task<int> GetLowStockCountAsync(string warehouseId)
+    {
+        // Simulate latency + random result
+        return Task.FromResult(_random.Next(0, 16));
+    }
+
+    /// <summary>
+    /// Called by the polling component. Fetches a new count and
+    /// broadcasts the result to every subscriber.
+    /// </summary>
+    public async Task RefreshAlertCountAsync(string warehouseId)
+    {
+        _lastAlertCount = await GetLowStockCountAsync(warehouseId);
+        if (OnAlertCountChanged is not null)
+            await OnAlertCountChanged.Invoke();
+    }
+}
+

