@using sv_530baa3ceff345fb8b21aecdc6f5eb6a.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-nowrap" for="warehouseSelect">Warehouse:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
            await WarehouseState.SetWarehouseAsync(newId);
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChangedAsync;
    }

    private async Task StateHasChangedAsync()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChangedAsync;
    }
}

