@page "/dashboard"
@using sv_530baa3ceff345fb8b21aecdc6f5eb6a.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">
    Currently viewing: <strong>@WarehouseState.CurrentWarehouseName</strong>
</p>

<div class="row g-4 mt-2">
    <div class="col-md-4">
        <div class="card @(AlertService.LastAlertCount > 0 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.LastAlertCount > 0 ? "text-danger" : "text-success")">
                    @AlertService.LastAlertCount
                </p>
                <p class="text-muted mb-0">
                    items below minimum level
                </p>
            </div>
            <div class="card-footer text-muted text-center">
                @if (_lastRefreshed is not null)
                {
                    <small>Last checked: @_lastRefreshed.Value.ToString("HH:mm:ss")</small>
                }
                else
                {
                    <small>Waiting for first poll…</small>
                }
                &nbsp;·&nbsp;
                <small>Refreshes every 10 s</small>
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Warehouse Info</h5>
                <dl class="row mb-0">
                    <dt class="col-sm-4">Warehouse ID</dt>
                    <dd class="col-sm-8"><code>@WarehouseState.CurrentWarehouseId</code></dd>
                    <dt class="col-sm-4">Name</dt>
